import{_ as a,o as s,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"52. The Preprocessor and Macros","description":"The Little Book of C — 52. The Preprocessor and Macros","frontmatter":{"title":"52. The Preprocessor and Macros","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Compilation and Build"],"description":"The Little Book of C — 52. The Preprocessor and Macros","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":52,"sidebarWeight":52,"lang":"en-US","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/052-The Preprocessor and Macros","alternateZh":"/posts/c教程/zh-CN/06-编译与构建/052-The Preprocessor and Macros"},"headers":[],"relativePath":"posts/c教程/en-US/06-Compilation and Build/052-The Preprocessor and Macros.md","filePath":"posts/c教程/en-US/06-Compilation and Build/052-The Preprocessor and Macros.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/06-Compilation and Build/052-The Preprocessor and Macros.md"};function o(p,e,d,c,l,r){return s(),n("div",null,[...e[0]||(e[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/06-编译与构建/052-The Preprocessor and Macros)</p><p>Before your C code is ever compiled, it passes through a powerful text-handling stage called the preprocessor. This is where headers are included, macros are expanded, and conditional compilation happens.</p><p>The preprocessor doesn’t “understand” C, it performs text substitution and file inclusion, preparing your code for the compiler.</p><h4 id="step-1-what-the-preprocessor-does" tabindex="-1">Step 1. What the Preprocessor Does <a class="header-anchor" href="#step-1-what-the-preprocessor-does" aria-label="Permalink to &quot;Step 1. What the Preprocessor Does&quot;">​</a></h4><p>Every line that starts with<code>#</code> is a preprocessor directive. Common ones include:</p><table tabindex="0"><thead><tr><th>Directive</th><th>Purpose</th></tr></thead><tbody><tr><td><code>#include</code></td><td>Insert contents of a header file</td></tr><tr><td><code>#define</code></td><td>Define a macro or constant</td></tr><tr><td><code>#undef</code></td><td>Remove a macro definition</td></tr><tr><td><code>#if</code>,<code>#ifdef</code>,<code>#ifndef</code></td><td>Conditional compilation</td></tr><tr><td><code>#else</code>,<code>#elif</code>,<code>#endif</code></td><td>Branch logic for the preprocessor</td></tr><tr><td><code>#error</code></td><td>Stop compilation with a message</td></tr><tr><td><code>#pragma</code></td><td>Compiler-specific instruction</td></tr></tbody></table><h4 id="tiny-code-see-it-in-action" tabindex="-1">Tiny Code: See It in Action <a class="header-anchor" href="#tiny-code-see-it-in-action" aria-label="Permalink to &quot;Tiny Code: See It in Action&quot;">​</a></h4><p>Create<code>macro.c</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#define PI 3.14159</span></span>
<span class="line"><span>#define CIRCLE_AREA(r) (PI * (r) * (r))</span></span>
<span class="line"><span>#define SQUARE(x) ((x) * (x))</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;PI = %.2f\\n&quot;, PI);</span></span>
<span class="line"><span>    printf(&quot;Area of circle (r=2): %.2f\\n&quot;, CIRCLE_AREA(2));</span></span>
<span class="line"><span>    printf(&quot;Square of 5: %d\\n&quot;, SQUARE(5));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc macro.c -o macro</span></span>
<span class="line"><span>./macro</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PI = 3.14</span></span>
<span class="line"><span>Area of circle (r=2): 12.57</span></span>
<span class="line"><span>Square of 5: 25</span></span></code></pre></div><h4 id="step-2-expanding-macros" tabindex="-1">Step 2. Expanding Macros <a class="header-anchor" href="#step-2-expanding-macros" aria-label="Permalink to &quot;Step 2. Expanding Macros&quot;">​</a></h4><p>You can inspect the preprocessor output before compilation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -E macro.c -o macro.i</span></span></code></pre></div><p>Open<code>macro.i</code>, you’ll see all<code>#include</code> files expanded and macros replaced with their values.</p><p>This is a great way to debug macro behavior or check how large standard headers expand.</p><h4 id="step-3-function-like-macros" tabindex="-1">Step 3. Function-Like Macros <a class="header-anchor" href="#step-3-function-like-macros" aria-label="Permalink to &quot;Step 3. Function-Like Macros&quot;">​</a></h4><p>Macros can look like functions, but they are expanded inline, meaning no call overhead, but also no type safety.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ADD(a, b) ((a) + (b))</span></span></code></pre></div><p>Usage:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;%d\\n&quot;, ADD(2, 3));  // becomes ((2) + (3))</span></span></code></pre></div><p>Be careful with missing parentheses:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define BAD_ADD(a, b) a + b</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, 2 * BAD_ADD(3, 4)); // expands to 2 * 3 + 4 → 10, not 14</span></span></code></pre></div><p>Always wrap parameters and entire expressions in parentheses.</p><h4 id="step-4-stringizing-and-token-pasting" tabindex="-1">Step 4. Stringizing and Token Pasting <a class="header-anchor" href="#step-4-stringizing-and-token-pasting" aria-label="Permalink to &quot;Step 4. Stringizing and Token Pasting&quot;">​</a></h4><p>Macros can manipulate text using special operators.</p><p>Stringizing (<code>#</code>) turns an argument into a string literal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define PRINT_EXPR(expr) printf(#expr &quot; = %d\\n&quot;, expr)</span></span></code></pre></div><p>Usage:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 5, y = 10;</span></span>
<span class="line"><span>PRINT_EXPR(x + y);  // prints: x + y = 15</span></span></code></pre></div><p>Token Pasting (<code>##</code>) concatenates tokens:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define MAKE_VAR(name, num) name##num</span></span>
<span class="line"><span>int MAKE_VAR(counter, 1) = 42;  // becomes int counter1 = 42;</span></span></code></pre></div><h4 id="step-5-conditional-compilation" tabindex="-1">Step 5. Conditional Compilation <a class="header-anchor" href="#step-5-conditional-compilation" aria-label="Permalink to &quot;Step 5. Conditional Compilation&quot;">​</a></h4><p>You can include or exclude code based on conditions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define DEBUG 1</span></span>
<span class="line"><span>#if DEBUG</span></span>
<span class="line"><span>    #define LOG(msg) printf(&quot;DEBUG: %s\\n&quot;, msg)</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    #define LOG(msg)</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>Usage:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    LOG(&quot;Starting program&quot;);</span></span>
<span class="line"><span>    printf(&quot;Running main logic\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile with or without<code>-DDEBUG=1</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -DDEBUG=1 log.c -o log</span></span></code></pre></div><p>You can also use:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifdef DEBUG</span></span>
<span class="line"><span>#ifndef RELEASE</span></span></code></pre></div><h4 id="step-6-header-guards" tabindex="-1">Step 6. Header Guards <a class="header-anchor" href="#step-6-header-guards" aria-label="Permalink to &quot;Step 6. Header Guards&quot;">​</a></h4><p>Prevent multiple inclusions of the same header file by using preprocessor guards:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MY_HEADER_H</span></span>
<span class="line"><span>#define MY_HEADER_H</span></span>
<span class="line"><span>void greet(void);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>If<code>MY_HEADER_H</code> is already defined, the contents are skipped. This prevents duplicate definitions across multiple includes.</p><h4 id="step-7-built-in-macros" tabindex="-1">Step 7. Built-in Macros <a class="header-anchor" href="#step-7-built-in-macros" aria-label="Permalink to &quot;Step 7. Built-in Macros&quot;">​</a></h4><p>The compiler defines a few handy macros automatically:</p><table tabindex="0"><thead><tr><th>Macro</th><th>Expands To</th></tr></thead><tbody><tr><td><code>__FILE__</code></td><td>current filename</td></tr><tr><td><code>__LINE__</code></td><td>current line number</td></tr><tr><td><code>__DATE__</code></td><td>compilation date</td></tr><tr><td><code>__TIME__</code></td><td>compilation time</td></tr><tr><td><code>__func__</code></td><td>current function name (C99+)</td></tr></tbody></table><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;Error at %s:%d in %s()\\n&quot;, __FILE__, __LINE__, __func__);</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error at macro.c:10 in main()</span></span></code></pre></div><h4 id="tiny-code-debug-macro" tabindex="-1">Tiny Code: Debug Macro <a class="header-anchor" href="#tiny-code-debug-macro" aria-label="Permalink to &quot;Tiny Code: Debug Macro&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define DEBUG_PRINT(fmt, ...) \\</span></span>
<span class="line"><span>    fprintf(stderr, &quot;[%s:%d] &quot; fmt &quot;\\n&quot;, __FILE__, __LINE__, __VA_ARGS__)</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x = 10;</span></span>
<span class="line"><span>    DEBUG_PRINT(&quot;x = %d&quot;, x);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[macro.c:5] x = 10</span></span></code></pre></div><p>This is how logging frameworks are implemented in C using macros.</p><h4 id="step-8-undefining-and-redefining" tabindex="-1">Step 8. Undefining and Redefining <a class="header-anchor" href="#step-8-undefining-and-redefining" aria-label="Permalink to &quot;Step 8. Undefining and Redefining&quot;">​</a></h4><p>You can remove a macro with<code>#undef</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#undef PI</span></span>
<span class="line"><span>#define PI 3.14</span></span></code></pre></div><p>This is often used in large projects to avoid macro name collisions between libraries.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>The preprocessor gives C flexibility and power at compile time, enabling:</p><ul><li>Cross-platform builds (conditional compilation)</li><li>Debug logging systems</li><li>Inline performance optimizations</li><li>Simplified configuration management</li></ul><p>It’s also a double-edged sword, overusing macros can make code hard to debug and maintain. Modern C favors inline functions for most use cases (see Section 54), but macros remain indispensable for low-level systems work.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a macro that swaps two variables without a temporary.</li><li>Implement a<code>LOG(level, msg)</code> macro that prints messages only if<code>level &gt;= MIN_LOG_LEVEL</code>.</li><li>Use<code>__DATE__</code> and<code>__TIME__</code> to print build information.</li><li>Add header guards to all your<code>.h</code> files and test multiple inclusions.</li><li>Try<code>gcc -E</code> on different programs to understand how preprocessing changes the source.</li></ol><p>In the next section, you’ll go deeper into conditional compilation, controlling which parts of your program are built based on platform, features, or debugging needs.</p>`,70)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
